        <div style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
          <div
            style={{
              color: 'var(--color-text-secondary)',
              fontSize: 15,
              fontWeight: 600,
              marginBottom: 8,
              overflow: 'hidden',
