                      onMouseEnter={(e) => {
                        e.currentTarget.style.background = 'rgba(255,77,79,0.1)'
                      }}
                      onMouseLeave={(e) => {
                        e.currentTarget.style.background = 'none'
                      }}
                    >
                      删除选中 ({selectedIds.length})
                    </button>
                  </Popconfirm>
                )}
              </div>

              <div
                style={{
                  display: 'grid',
                  gridTemplateColumns: 'repeat(2, 1fr)',
                  gap: 16,
                }}
              >
                {items.map((item) => (
                  <WishlistCard
                    key={item.id}
                    item={item}
                    selected={selectedIds.includes(item.id)}
                    onSelect={(checked) => handleSelectItem(item.id, checked)}
                    onRemove={() => handleRemove(item.productId)}
                    onAddToCart={() => handleAddToCart(item)}
                  />
                ))}
              </div>

              {hasMore && (
                <div style={{ display: 'flex', justifyContent: 'center', padding: '32px 0' }}>
                  <button
                    onClick={handleLoadMore}
                    disabled={loading}
                    style={{
                      padding: '10px 32px',
                      border: '1px solid rgba(var(--color-primary-rgb), 0.3)',
                      borderRadius: 8,
                      background: 'rgba(var(--color-primary-rgb), 0.06)',
                      color: 'var(--color-primary)',
                      fontSize: 14,
                      fontWeight: 500,
                      cursor: loading ? 'not-allowed' : 'pointer',
                      transition: 'all 0.25s ease',
                      display: 'flex',
                      alignItems: 'center',
                      gap: 8,
                      opacity: loading ? 0.5 : 1,
                    }}
                    onMouseEnter={(e) => {
                      if (!loading) {
                        e.currentTarget.style.background = 'rgba(var(--color-primary-rgb), 0.12)'
                        e.currentTarget.style.borderColor = 'rgba(var(--color-primary-rgb), 0.5)'
                        e.currentTarget.style.boxShadow = '0 2px 12px rgba(var(--color-primary-rgb), 0.15)'
                      }
                    }}
                    onMouseLeave={(e) => {
