import { useState, useRef, useEffect, useCallback } from 'react'
import {
  PlusOutlined,
  DeleteOutlined,
  PictureOutlined,
  VideoCameraOutlined,
  SendOutlined,
  SaveOutlined,
  TagOutlined,
  ShoppingOutlined,
} from '@ant-design/icons'
import { history, useSearchParams } from 'umi'
import { message, Spin, Modal } from 'antd'
import TiptapEditor from '@/components/TiptapEditor'
import { createPost, getPostDetail, updatePost, saveDraft } from '@/api/community'
import { uploadFile } from '@/api/file'
import { useAuthStore } from '@/stores/auth'

interface MediaItem {
  uid: string
  type: 'image' | 'video'
  url: string
  file?: File
}

export default function Publish() {
  const { isAuthenticated } = useAuthStore()
  const [searchParams] = useSearchParams()
  const editPostId = searchParams.get('edit')
  const isEditing = editPostId != null

  useEffect(() => {
    if (!isAuthenticated) {
      message.warning('请先登录')
      history.replace('/login?redirect=/publish')
    }
  }, [isAuthenticated])

  if (!isAuthenticated) {
    return (
      <div style={{ minHeight: '100vh', background: 'var(--color-bg-base)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <Spin size="large" />
      </div>
    )
  }

  const [title, setTitle] = useState('')
  const [content, setContent] = useState('')
  const [mediaList, setMediaList] = useState<MediaItem[]>([])
  const [tags, setTags] = useState('')
  const [linkProduct, setLinkProduct] = useState(false)
  const [productName, setProductName] = useState('')
  const [productPrice, setProductPrice] = useState('')
  const [publishing, setPublishing] = useState(false)
  const [savingDraft, setSavingDraft] = useState(false)
  const [draftId, setDraftId] = useState<number | null>(null)
  const [loadingPost, setLoadingPost] = useState(isEditing)
  const imageInputRef = useRef<HTMLInputElement>(null)
  const videoInputRef = useRef<HTMLInputElement>(null)
  const leavingRef = useRef(false)

  const hasContent = title.trim() || content.trim() || mediaList.length > 0

  // Intercept browser back/close when there's unsaved content
  useEffect(() => {
    if (!hasContent || leavingRef.current) return

    const handleBeforeUnload = (e: BeforeUnloadEvent) => {
      e.preventDefault()
    }

    const handlePopState = () => {
      window.history.pushState(null, '', window.location.href)
      Modal.confirm({
        title: '确认离开',
        content: '当前有未保存的内容，离开后将丢失，确认离开吗？',
        okText: '确认离开',
        cancelText: '继续编辑',
        onOk: () => {
          leavingRef.current = true
          history.back()
        },
      })
    }

    window.addEventListener('beforeunload', handleBeforeUnload)
    window.history.pushState(null, '', window.location.href)
    window.addEventListener('popstate', handlePopState)

    return () => {
      window.removeEventListener('beforeunload', handleBeforeUnload)
      window.removeEventListener('popstate', handlePopState)
    }
  }, [hasContent])

  useEffect(() => {
    if (!editPostId) return

    const fetchPost = async () => {
      setLoadingPost(true)
      try {
        const { data: res } = await getPostDetail(Number(editPostId))
        const post = res.data
        setTitle(post.title)
        setContent(post.content)

        if (post.mediaUrls?.length) {
          const existingMedia: MediaItem[] = post.mediaUrls.map((url: string, index: number) => ({
            uid: `existing-${index}`,
            type: post.mediaType === 'VIDEO' ? 'video' : 'image',
            url,
          }))
          setMediaList(existingMedia)
        }

        if (post.tags?.length) {
          setTags(post.tags.map((t: { name: string }) => t.name).join(' '))
        }

        if (post.productId) {
          setLinkProduct(true)
        }
      } catch {
        message.error('加载帖子失败')
        history.back()
      } finally {
        setLoadingPost(false)
      }
    }

    fetchPost()
  }, [editPostId])

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files
    if (!files) return
    const newItems: MediaItem[] = Array.from(files).map((f) => ({
      uid: `${Date.now()}-${f.name}`,
      type: 'image' as const,
      url: URL.createObjectURL(f),
      file: f,
    }))
    setMediaList((prev) => [...prev, ...newItems])
    e.target.value = ''
  }

  const handleVideoSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    setMediaList((prev) => [
      ...prev,
      {
        uid: `${Date.now()}-${file.name}`,
        type: 'video',
        url: URL.createObjectURL(file),
        file,
      },
    ])
    e.target.value = ''
  }

  const removeMedia = (uid: string) => {
    setMediaList((prev) => {
      const item = prev.find((i) => i.uid === uid)
      if (item) URL.revokeObjectURL(item.url)
      return prev.filter((i) => i.uid !== uid)
    })
  }

  const handlePublish = async () => {
    if (!title.trim()) {
      message.warning('请输入标题')
      return
    }
    if (!content.trim() && mediaList.length === 0) {
      message.warning('请输入内容或添加媒体文件')
      return
    }
    setPublishing(true)
    try {
      const uploadedUrls: string[] = []
      for (const item of mediaList) {
        if (item.file) {
          try {
            const res = await uploadFile(item.file)
            const url = res.data?.data?.url
            if (url) uploadedUrls.push(url)
          } catch {
            // Skip failed uploads
          }
        } else {
          uploadedUrls.push(item.url)
        }
      }

      const mediaType = uploadedUrls.length === 0
        ? 'IMAGE'
        : mediaList.some((m) => m.type === 'video') && mediaList.some((m) => m.type === 'image')
          ? 'MIXED'
          : mediaList.some((m) => m.type === 'video')
            ? 'VIDEO'
            : 'IMAGE'

      const coverImage = uploadedUrls.length > 0 ? uploadedUrls[0] : ''

      const postData = {
        title: title.trim(),
        content,
        coverImage,
        mediaUrls: JSON.stringify(uploadedUrls),
        mediaType,
        tagIds: [] as number[],
      }

      if (isEditing && editPostId) {
        await updatePost(Number(editPostId), postData)
        message.success('更新成功！')
        history.push(`/post/${editPostId}`)
      } else {
        const res = await createPost(postData)
        message.success('发布成功！')
        const postId = res.data?.data?.id
        if (postId) {
          history.push(`/post/${postId}`)
        } else {
          history.push('/')
        }
      }
    } catch {
      message.error(isEditing ? '更新失败，请稍后重试' : '发布失败，请稍后重试')
    } finally {
      setPublishing(false)
    }
  }

  const handleSaveDraft = async () => {
    Modal.confirm({
      title: '保存草稿',
      content: '确认将当前内容保存为草稿吗？',
      okText: '确认保存',
      cancelText: '取消',
      onOk: async () => {
        setSavingDraft(true)
        try {
          const uploadedUrls: string[] = []
          for (const item of mediaList) {
            if (item.file) {
              try {
                const res = await uploadFile(item.file)
                const url = res.data?.data?.url
                if (url) uploadedUrls.push(url)
              } catch {
                // Skip failed uploads
              }
            } else {
              uploadedUrls.push(item.url)
            }
          }

          const mediaType = uploadedUrls.length === 0
            ? 'IMAGE'
            : mediaList.some((m) => m.type === 'video') && mediaList.some((m) => m.type === 'image')
              ? 'MIXED'
              : mediaList.some((m) => m.type === 'video')
                ? 'VIDEO'
                : 'IMAGE'

          const coverImage = uploadedUrls.length > 0 ? uploadedUrls[0] : ''

          const res = await saveDraft({
            id: draftId ?? (isEditing ? Number(editPostId) : undefined),
            title: title.trim() || '未命名草稿',
            content,
            coverImage,
            mediaUrls: uploadedUrls,
            mediaType,
            tagIds: [],
          })
          const newDraftId = res.data?.data?.id
          if (newDraftId) setDraftId(newDraftId)
          message.success('草稿已保存')
        } catch {
          message.error('保存草稿失败')
        } finally {
          setSavingDraft(false)
        }
      },
    })
  }

  if (loadingPost) {
    return (
      <div style={{ minHeight: '100vh', background: 'var(--color-bg-base)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <Spin size="large" />
      </div>
    )
  }

  return (
    <div style={{ minHeight: '100vh', background: 'var(--color-bg-base)', padding: '24px' }}>
      <div style={{ maxWidth: 800, margin: '0 auto' }}>
        <div style={{
