            {isEditing ? '编辑内容' : '发布内容'}
          </h1>
          <div style={{ display: 'flex', gap: 12 }}>
            <button
              type="button"
              onClick={() => {
                Modal.confirm({
                  title: '确认取消',
                  content: '取消后未保存的内容将丢失，确认取消吗？',
                  okText: '确认取消',
                  cancelText: '继续编辑',
                  onOk: () => { leavingRef.current = true; history.back() },
                })
              }}
              style={{
                padding: '8px 20px',
                border: '1px solid var(--color-border)',
                borderRadius: '8px',
                background: 'transparent',
                color: 'var(--color-text-secondary)',
