function ConfirmDialog({
  open,
  title,
  content,
  okText = '确定',
  cancelText = '取消',
  danger = false,
  onOk,
  onCancel,
}: {
  open: boolean
  title: string
  content: string
  okText?: string
  cancelText?: string
  danger?: boolean
  onOk: () => void
  onCancel: () => void
}) {
  if (!open) return null
  return createPortal(
    <div style={{
      position: 'fixed',
      inset: 0,
      background: 'rgba(0, 0, 0, 0.6)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      zIndex: 10000,
      backdropFilter: 'blur(4px)',
