            fontWeight: 600,
            cursor: 'pointer',
            transition: 'all 0.2s',
            minWidth: 100,
            boxShadow: danger
              ? '0 4px 16px rgba(255, 71, 87, 0.3)'
              : '0 4px 16px rgba(var(--color-primary-rgb), 0.3)',
          }}>
            {okText}
          </button>
        </div>
      </div>
    </div>,
    document.body,
  )
}

