        title={editingRecord ? '编辑菜单' : '新增菜单'}
        open={modalVisible}
        onOpenChange={createHandleOpenChange(setModalVisible, () => setEditingRecord(null))}
        onFinish={handleSubmit}
        initialValues={
          editingRecord
            ? {
                ...editingRecord,
                visible: editingRecord.visible === 1,
                status: editingRecord.status === 1,
              }
            : { visible: true, status: true, orderNum: 0, menuType: 1, parentId: 0 }
        }
        modalProps={{ destroyOnHidden: true, maskClosable: false, keyboard: false }}
        width={600}
      >
        <ProFormTreeSelect
          name="parentId"
          label="上级菜单"
          fieldProps={{
            treeData: treeSelectData,
            placeholder: '请选择上级菜单',
            treeDefaultExpandAll: true,
            allowClear: true,
          }}
        />
        <ProFormSelect
          name="menuType"
          label="菜单类型"
          options={[
            { label: '目录', value: 0 },
            { label: '菜单', value: 1 },
            { label: '按钮', value: 2 },
          ]}
          rules={[{ required: true, message: '请选择菜单类型' }]}
        />
        <ProFormText
          name="menuName"
          label="菜单名称"
          placeholder="请输入菜单名称"
          rules={[{ required: true, message: '请输入菜单名称' }]}
        />
        <ProFormSelect
          name="icon"
          label="图标"
          options={ICON_OPTIONS}
          showSearch
          fieldProps={{ allowClear: true, placeholder: '请选择图标' }}
        />
        <ProFormText
          name="path"
          label="路由地址"
          placeholder="请输入路由地址"
        />
        <ProFormText
          name="component"
          label="组件路径"
          placeholder="请输入组件路径"
        />
        <ProFormText
          name="perms"
          label="权限标识"
          placeholder="如 system:user:list"
        />
        <ProFormDigit
          name="orderNum"
          label="排序"
          min={0}
          fieldProps={{ precision: 0 }}
        />
        <ProFormSwitch name="visible" label="是否可见" />
        <ProFormSwitch name="status" label="状态" />
