                style={styles.darkInput}
              />
            </Form.Item>

            <Form.Item
              name="password"
              rules={[{ required: true, message: '请输入密码' }]}
              style={styles.inputWrapper}
            >
              <Input.Password
                prefix={
                  <LockOutlined style={{ color: 'var(--color-text-secondary)', fontSize: '16px' }} />
                }
                placeholder="密码"
                style={styles.darkInput}
              />
